import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        String p = br.readLine().trim();

        for (int len = 1; len <= n / 2; len++) {
            if (n % len != 0) {
                continue;
            }

            int[] rootCount = new int[26];
            for (int i = 0; i < len; i++) {
                rootCount[p.charAt(i) - 'a']++;
            }

            boolean valid = true;
            int[] blockCount = new int[26];

            for (int start = len; start < n && valid; start += len) {
                Arrays.fill(blockCount, 0);
                for (int i = start; i < start + len; i++) {
                    blockCount[p.charAt(i) - 'a']++;
                }
                valid = Arrays.equals(rootCount, blockCount);
            }

            if (valid) {
                System.out.println(p.substring(0, len));
                return;
            }
        }

        System.out.println("*");
    }
}
